WITH remaining_keys AS (SELECT category, id FROM products EXCEPT SELECT category, id FROM products WHERE stock_qty BETWEEN 286 AND 320), kept_rows AS (SELECT s.* FROM products s JOIN remaining_keys k ON s.category = k.category AND s.id = k.id) SELECT category, AVG(price) AS avg_price, PERCENTILE_APPROX(price, 0.5) AS price_p50, SORT_ARRAY(COLLECT_SET(category)) AS category_list FROM kept_rows GROUP BY category ORDER BY avg_price DESC NULLS FIRST
